import{_ as r,o as e,c as a,ag as d}from"./chunks/framework.4s5LDCII.js";const _=JSON.parse('{"title":"中国居民膳食指南（2022）","description":"中国营养学会《中国居民膳食指南（2022）》八准则的可执行整理。出处为中国营养学会官网公开页面。","frontmatter":{"title":"中国居民膳食指南（2022）","issuer":"中国营养学会","source_tier":"二级来源","version":2022,"published":"2022-04","source_url":"http://dg.cnsoc.org/","status":"现行","tags":["膳食指南","营养","健康饮食","行动清单"],"reviewed":false,"description":"中国营养学会《中国居民膳食指南（2022）》八准则的可执行整理。出处为中国营养学会官网公开页面。"},"headers":[],"relativePath":"guides/dietary-guidelines-2022.md","filePath":"guides/dietary-guidelines-2022.md"}'),o={name:"guides/dietary-guidelines-2022.md"};function n(s,t,h,l,g,i){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="中国居民膳食指南-2022" tabindex="-1">中国居民膳食指南（2022） <a class="header-anchor" href="#中国居民膳食指南-2022" aria-label="Permalink to &quot;中国居民膳食指南（2022）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据中国营养学会官网公开内容整理，尚未逐条对照原文校验；校验通过前请以官网及出版物为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页内容整理自中国营养学会公开发布的准则与核心推荐（<strong>二级来源</strong>，行业专业机构）。本站不构成诊疗建议。</p></div><blockquote><p><strong>原文出处</strong>：中国营养学会发布（<a href="http://dg.cnsoc.org/" target="_blank" rel="noreferrer">膳食指南官网</a>）· 二级来源。本指南为出版图书，无官方免费全文 PDF；&quot;出处&quot;链接指向官网公开的准则页。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>所有一般人群——它是日常&quot;怎么吃&quot;的总纲；具体到某一种疾病（如高血压、糖尿病），请再配合卫健委对应的食养指南词条阅读。</p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p><strong>八条准则</strong>：① 食物多样，合理搭配 ② 吃动平衡，健康体重 ③ 多吃蔬果、奶类、全谷、大豆 ④ 适量吃鱼、禽、蛋、瘦肉 ⑤ 少盐少油，控糖限酒 ⑥ 规律进餐，足量饮水 ⑦ 会烹会选，会看标签 ⑧ 公筷分餐，杜绝浪费。（<a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则一</a>、<a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则二</a>）</p><table tabindex="0"><thead><tr><th>关键数字（每日，除注明外）</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>食物品种</td><td>至少 <strong>12 种/日</strong>，<strong>25 种/周</strong></td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则一</a></td></tr><tr><td>食盐</td><td><strong>&lt;5g</strong></td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则五</a></td></tr><tr><td>烹调油</td><td><strong>25～30g</strong></td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则五</a></td></tr><tr><td>添加糖</td><td><strong>&lt;50g，最好 &lt;25g</strong></td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则五</a></td></tr><tr><td>酒精</td><td><strong>≤15g/日</strong>（任何年龄都不推荐饮酒）</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则五</a></td></tr><tr><td>水</td><td>男 <strong>1700mL</strong>、女 <strong>1500mL</strong></td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则六</a></td></tr><tr><td>身体活动</td><td>相当于每天 <strong>6000 步</strong>以上</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则二</a></td></tr><tr><td>蔬菜 / 水果</td><td><strong>300～500g / 200～350g</strong></td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则三</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🛒-买-🍚-吃" tabindex="-1">🛒 买 / 🍚 吃 <a class="header-anchor" href="#🛒-买-🍚-吃" aria-label="Permalink to &quot;🛒 买 / 🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>按五大类食物搭配采购：谷薯、蔬果、鱼禽蛋肉、大豆坚果、油盐</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则一</a></td></tr><tr><td>餐餐有蔬菜、天天有水果；经常吃全谷物、大豆制品；吃各种奶制品</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则三</a></td></tr><tr><td>鱼、禽、蛋、瘦肉适量，优先鱼禽</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则四</a></td></tr><tr><td>少盐少油控糖限酒；足量饮水，不喝或少喝含糖饮料</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则五、六</a></td></tr><tr><td>【本站提示】预包装食品看营养成分表与配料表——&quot;会看标签&quot;是准则七</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则七</a></td></tr></tbody></table><h3 id="🍳-做-🏃-动" tabindex="-1">🍳 做 / 🏃 动 <a class="header-anchor" href="#🍳-做-🏃-动" aria-label="Permalink to &quot;🍳 做 / 🏃 动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>在家做饭、学习烹饪，传承健康饮食文化</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则七</a></td></tr><tr><td>坚持日常身体活动，每周中等强度运动 150 分钟以上</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则二</a></td></tr><tr><td>公筷分餐、杜绝浪费</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则八</a></td></tr></tbody></table><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>指南怎么说</th><th>出处</th></tr></thead><tbody><tr><td>&quot;水果多吃没事&quot;</td><td>水果 200～350g 适量，果汁不能代替鲜果</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则三</a></td></tr><tr><td>&quot;喝点酒养生&quot;</td><td>成人每日酒精 ≤15g，且任何年龄都不推荐饮酒</td><td><a href="http://dg.cnsoc.org/newslist_0402_1.htm" target="_blank" rel="noreferrer">准则五</a></td></tr></tbody></table><h2 id="与疾病食养指南的关系" tabindex="-1">与疾病食养指南的关系 <a class="header-anchor" href="#与疾病食养指南的关系" aria-label="Permalink to &quot;与疾病食养指南的关系&quot;">​</a></h2><p>把八准则当&quot;总纲&quot;执行；家里有慢病患者时，再看本站对应的疾病食养指南词条（如<a href="/SageRelay/guides/hypertension-2023.html">高血压</a>、<a href="/SageRelay/guides/diabetes-2023.html">糖尿病</a>），那里有更细的量化要求。</p><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>中国营养学会（<strong>二级来源</strong>）</td></tr><tr><td>版本</td><td>2022 版（现行）</td></tr><tr><td>发布时间</td><td>2022 年 4 月</td></tr><tr><td>原文链接</td><td><a href="http://dg.cnsoc.org/" target="_blank" rel="noreferrer">膳食指南官网</a>（全文为出版图书《中国居民膳食指南（2022）》）</td></tr></tbody></table>',20)])])}const b=r(o,[["render",n]]);export{_ as __pageData,b as default};
